const webhookData = $('Webhook Lead Intake').first().json;
const body = webhookData.body || webhookData;

let lead = {};
const srcRaw = (body.source || body.utm_source || '').toLowerCase();
let source = 'Website';
if (srcRaw.includes('facebook') || srcRaw.includes('fb')) source = 'Facebook';
else if (srcRaw.includes('google')) source = 'Google';
else if (srcRaw.includes('tiktok')) source = 'TikTok';
else if (srcRaw.includes('zalo')) source = 'Zalo OA';
else if (srcRaw.includes('ao')) source = 'AO Web';
else if (body.source) source = body.source;

// Facebook Lead Ads direct webhook
if (body.entry && body.entry[0] && body.entry[0].changes) {
  const chg = body.entry[0].changes[0].value || {};
  lead = {
    source: 'Facebook',
    campaign_name: '', ad_set: '', ad_name: '',
    name: '', phone: '', email: '',
    message: 'Facebook Lead ID: ' + (chg.leadgen_id || 'N/A'),
    brand: 'Chưa xác định',
    leadgen_id: chg.leadgen_id || '',
    page_id: chg.page_id || '',
    ad_id: chg.ad_id || '',
  };
} else {
  lead = {
    source: source,
    campaign_name: body.campaign_name || body.utm_campaign || '',
    ad_set: body.ad_set || body.ad_set_name || body.utm_content || '',
    ad_name: body.ad_name || '',
    name: body.name || body.full_name || body.ho_ten || '',
    phone: body.phone || body.phone_number || body.sdt || '',
    email: body.email || '',
    message: body.message || body.note || body.yeu_cau || body.content || '',
    brand: body.brand || 'Chưa xác định',
  };
}

// Auto-detect brand
const txt = ((lead.message || '') + ' ' + (lead.name || '')).toLowerCase();
if (lead.brand === 'Chưa xác định' || !lead.brand) {
  if (txt.includes('xe nang') || txt.includes('nang nguoi') || txt.includes('mhrental') || txt.includes('aerial') || txt.includes('boom') || txt.includes('scissor')) {
    lead.brand = 'MHrental';
  } else if (txt.includes('pin') || txt.includes('ac quy') || txt.includes('lithium') || txt.includes('mhpower') || txt.includes('battery') || txt.includes('accu')) {
    lead.brand = 'MHpower';
  }
}

lead.created_at = new Date().toISOString();
lead.status = 'Mới';
lead.raw_data = JSON.stringify(body).substring(0, 500);

return [{ json: lead }];

const lead = $input.first().json;

const prompt = `Chấm điểm lead B2B cho MHrental (xe nâng người - aerial work platform, boom lift, scissor lift) và MHpower (Pin Lithium & Ắc Quy Khô công nghiệp).

Thang diem:
A = Rất nóng: Cần gấp trong ngày/tuần, SĐT rõ ràng, nhu cầu kỹ thuật cụ thể (model xe, công suất pin, số lượng...)
B = Tiềm năng: Có nhu cầu thật nhưng thiếu thông tin kỹ thuật hoặc timeline
C = Tham khảo: Đang tìm hiểu chung, không gấp
D = Loại bỏ: Spam, sai đối tượng, không SĐT, thông tin không hợp lệ

Thong tin lead:
Tên: ${lead.name || 'Không có'}
SĐT: ${lead.phone || 'Không có'}
Email: ${lead.email || 'Không có'}
Nội dung: ${lead.message || 'Không có'}
Nguồn: ${lead.source}
Brand: ${lead.brand}

CHỈ trả về JSON hợp lệ. Không markdown. Không giải thích. Không prefix:
{"score":"A|B|C|D","reason":"<50 ký tự>","brand_confirmed":"MHrental|MHpower|Chưa xác định","suggested_product":"<tên sản phẩm>","urgency":"Gấp trong ngày|Trong tuần|Trong tháng|Tham khảo"}`;

return [{
  json: {
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 300,
    messages: [{ role: 'user', content: prompt }]
  }
}];

const aiResp = $input.first().json;
const lead = $('Normalize Lead Data').first().json;

let score = { score: 'C', reason: 'Không phân tích được', brand_confirmed: lead.brand, suggested_product: '', urgency: 'Tham khảo' };

try {
  const textBlock = Array.isArray(aiResp.content) ? aiResp.content.find(b => b.type === 'text') : null;
  const text = (textBlock ? textBlock.text : '').trim();
  let parsed = null;
  try { parsed = JSON.parse(text); } catch(e1) {
    const match = text.match(/\{[\s\S]*?\}/);
    if (match) try { parsed = JSON.parse(match[0]); } catch(e2) {}
  }
  if (parsed) score = { ...score, ...parsed };
} catch(e) {
  score.reason = 'Lỗi phân tích: ' + e.message;
}

const labels = { A: 'A - Rất nóng', B: 'B - Tiềm năng', C: 'C - Tham khảo', D: 'D - Loại bỏ' };

return [{
  json: {
    ...lead,
    ai_score: score.score || 'C',
    ai_reason: score.reason || '',
    brand: score.brand_confirmed || lead.brand,
    suggested_product: score.suggested_product || '',
    urgency: score.urgency || 'Tham khảo',
    score_label: labels[score.score] || 'C - Tham khảo',
  }
}];

const lead = $input.first().json;
const isRental = lead.brand === 'MHrental';
const base = isRental ? 'RYfKboTX0arHkRspUwMlMEUkgMd' : 'ZxFDb2v4Fa3lcKssShclLMzSgLh';
const leadsTable = isRental ? 'tbldDVBv7XtDEsen' : 'tbliHIVs89nmwY0G';
const aiSummary = '[' + lead.ai_score + '] ' + lead.score_label + '\nNguồn: ' + lead.source + ' | Brand: ' + lead.brand + '\nSản phẩm: ' + (lead.suggested_product||'Chưa rõ') + '\nMức gấp: ' + lead.urgency + '\nAI: ' + (lead.ai_reason||'') + '\n---\n' + (lead.message||'').substring(0,300);
const fields = {
  'Người liên hệ': lead.name || 'Chưa có tên',
  'Email': lead.email || '',
  'Khách mới/cũ': 'Khách mới'
};
if (lead.phone) fields['SĐT'] = lead.phone;
if (!isRental) fields['Ghi chú'] = aiSummary;
const nguonMap = { 'Facebook':'facebook', 'Google':'google', 'Zalo OA':'Zalo', 'Zalo':'Zalo', 'Messenger':'Messenger' };
if (!isRental && nguonMap[lead.source]) fields['Nguồn'] = nguonMap[lead.source];
const url = 'https://open.larksuite.com/open-apis/bitable/v1/apps/' + base + '/tables/' + leadsTable + '/records';
return [{ json: { fields, _url: url, _lead: lead } }];

const lead = $('Parse AI Score').first().json;

return [{
  json: {
    msg_type: 'interactive',
    card: {
      config: { wide_screen_mode: true },
      header: {
        title: { tag: 'plain_text', content: '🔥 LEAD A - GỌI NGAY trong 5 phút!' },
        template: 'red'
      },
      elements: [
        {
          tag: 'div',
          fields: [
            { is_short: true, text: { tag: 'lark_md', content: '**Tên:** ' + (lead.name || 'Chưa có') } },
            { is_short: true, text: { tag: 'lark_md', content: '**SĐT:** ' + (lead.phone || 'CHƯA CÓ SĐT') } },
            { is_short: true, text: { tag: 'lark_md', content: '**Nguồn:** ' + (lead.source || '') } },
            { is_short: true, text: { tag: 'lark_md', content: '**Brand:** ' + (lead.brand || '') } },
            { is_short: true, text: { tag: 'lark_md', content: '**Mức gấp:** ' + (lead.urgency || '') } },
            { is_short: true, text: { tag: 'lark_md', content: '**Sản phẩm:** ' + (lead.suggested_product || 'Chưa rõ') } },
            { is_short: false, text: { tag: 'lark_md', content: '**Nhu cầu:** ' + (lead.message || '').substring(0, 200) } },
            { is_short: false, text: { tag: 'lark_md', content: '**AI nhận xét:** ' + (lead.ai_reason || '') } }
          ]
        }
      ]
    }
  }
}];

const data = $input.first().json;
const VALID_SCORES = ['A', 'B', 'C', 'D'];
const URGENCY_MAP = [['gấp trong ngày','Gấp trong ngày'],['hôm nay','Gấp trong ngày'],['khẩn','Gấp trong ngày'],['high','Gấp trong ngày'],['trong tuần','Trong tuần'],['tuần','Trong tuần'],['medium','Trong tuần'],['trong tháng','Trong tháng'],['tháng','Trong tháng'],['low','Trong tháng'],['tham khảo','Tham khảo']];
const rawScore = (data.ai_score || '').toUpperCase().trim().charAt(0);
const validScore = VALID_SCORES.includes(rawScore) ? rawScore : 'C';
if (validScore !== data.ai_score) console.warn('[Schema] Score normalized: "' + data.ai_score + '" → "' + validScore + '"');
const urgencyLower = (data.urgency || '').toLowerCase().trim();
let normalizedUrgency = 'Tham khảo';
for (const [key, mapped] of URGENCY_MAP) { if (urgencyLower.includes(key)) { normalizedUrgency = mapped; break; } }
const labels = { A: 'A - Rất nóng', B: 'B - Tiềm năng', C: 'C - Tham khảo', D: 'D - Loại bỏ' };
return [{ json: { ...data, ai_score: validScore, score_label: labels[validScore], urgency: normalizedUrgency, _schema_validated: true, _raw_score: data.ai_score, _raw_urgency: data.urgency } }];

const body = $('Webhook FB Lead POST').first().json.body;

let leadgen_id = '', page_id = '', ad_id = '';
let comment_id = '', commenter_id = '', comment_text = '', post_id = '';

if (body && body.entry && body.entry[0]) {
  const entry = body.entry[0];
  page_id = entry.id || '';
  if (entry.changes && entry.changes[0]) {
    const change = entry.changes[0];
    if (change.value) {
      leadgen_id = change.value.leadgen_id || '';
      ad_id = change.value.ad_id || '';
      if (!page_id) page_id = change.value.page_id || '';
      if (change.value.item === 'comment') {
        const verb = change.value.verb || 'add';
        const fromId = (change.value.from && change.value.from.id) || '';
        if (verb === 'add' && fromId && fromId !== page_id) {
          comment_id = change.value.comment_id || '';
          commenter_id = fromId;
          comment_text = change.value.message || '';
          post_id = change.value.post_id || change.value.parent_id || '';
        }
      }
    }
  }
}

let event_type = 'unknown', psid = '', msg_text = '';

if (body && body.entry && body.entry[0]) {
  const entry = body.entry[0];
  if (entry.messaging && entry.messaging[0]) {
    const msg = entry.messaging[0];
    psid = msg.sender ? msg.sender.id : '';
    if (msg.message && msg.message.text) {
      event_type = 'message';
      msg_text = msg.message.text;
    } else if (msg.message && msg.message.attachments && msg.message.attachments.length > 0) {
      event_type = 'message';
      const att = msg.message.attachments[0];
      msg_text = att.type === 'image' ? '[Khách gửi hình ảnh]' : ('[' + (att.type || 'file') + ']');
    } else if (msg.postback) {
      const postbackMap = { 'GET_STARTED': 'Xin chào', 'MENU_PRICING': 'Cho hỏi giá pin', 'MENU_PRODUCT': 'Giới thiệu sản phẩm SuperV' };
      event_type = 'message';
      msg_text = postbackMap[msg.postback.payload || ''] || 'Xin chào';
    } else {
      event_type = 'message_other';
    }
  } else if (comment_id && commenter_id) {
    event_type = 'comment';
  } else if (leadgen_id) {
    event_type = 'leadgen';
  }
}

return [{ json: { leadgen_id, page_id, ad_id, event_type, psid, msg_text, comment_id, commenter_id, comment_text, post_id } }];

const fbLead = $input.first().json;
const extractData = $('Extract FB leadgen_id').first().json;

// Test injection: skip FB Graph API for test_fb_ leadgen IDs
if (extractData.leadgen_id && extractData.leadgen_id.startsWith('test_fb_')) {
  const isRental = extractData.leadgen_id.indexOf('mhrental') !== -1 || extractData.leadgen_id.indexOf('rental') !== -1;
  return [{ json: {
    source: 'Facebook',
    campaign_name: isRental ? 'MHrental - Xe nang nguoi 2026' : 'MHpower - Pin Lithium 2026',
    ad_set: isRental ? 'xe nang nguoi - retarget' : 'pin lithium 48v',
    ad_name: isRental ? 'boom lift 10m' : 'pin xe nang 48v',
    name: isRental ? 'Trần Test Rental' : 'Lê Test Power',
    phone: '0901234567',
    email: 'test@example.com',
    message: isRental ? 'Cần 2 xe nâng người 10m cho công trình xây dựng' : 'Cần mua pin lithium 48V cho 3 xe nâng hàng',
    brand: isRental ? 'MHrental' : 'MHpower',
    leadgen_id: extractData.leadgen_id,
    created_at: new Date().toISOString(),
    status: 'Mới',
    raw_data: '[]'
  }}];
}

const fieldData = fbLead.field_data || [];
let name = '', phone = '', email = '', message = '';

for (const field of fieldData) {
  const val = (field.values || [])[0] || '';
  const fn = (field.name || '').toLowerCase();
  if (fn.includes('name') || fn === 'ho_ten' || fn === 'full_name') name = val;
  else if (fn.includes('phone') || fn.includes('sdt') || fn === 'phone_number') phone = val;
  else if (fn.includes('email')) email = val;
  else if (fn.includes('message') || fn.includes('note') || fn.includes('nhu_cau') || fn.includes('yeu_cau')) message = val;
}

if (!message && fieldData.length > 0) {
  message = fieldData.map(f => f.name + ': ' + (f.values || []).join(', ')).join(' | ').replace(/_/g, ' ');
}

const campaignText = ((fbLead.campaign_name || '') + ' ' + (fbLead.adset_name || '') + ' ' + (fbLead.ad_name || '')).toLowerCase();
let brand = 'MHpower';
if (campaignText.includes('xe nang') || campaignText.includes('mhrental') || campaignText.includes('aerial') || campaignText.includes('boom')) {
  brand = 'MHrental';
}

return [{
  json: {
    source: 'Facebook',
    campaign_name: fbLead.campaign_name || '',
    ad_set: fbLead.adset_name || '',
    ad_name: fbLead.ad_name || '',
    name: name || 'Chưa có tên',
    phone: phone || '',
    email: email || '',
    message: message || '',
    brand: brand,
    leadgen_id: extractData.leadgen_id || fbLead.id || '',
    created_at: new Date().toISOString(),
    status: 'Mới',
    raw_data: JSON.stringify(fieldData).substring(0, 500)
  }
}];

