const lead = $('Parse AI Score').first().json;

return [{
  json: {
    msg_type: 'interactive',
    card: {
      config: { wide_screen_mode: true },
      header: {
        title: { tag: 'plain_text', content: '🔥 LEAD FACEBOOK - GỌI NGAY!' },
        template: 'red'
      },
      elements: [
        {
          tag: 'div',
          fields: [
            { is_short: true, text: { tag: 'lark_md', content: '**Tên:** ' + (lead.name || 'Chưa có') } },
            { is_short: true, text: { tag: 'lark_md', content: '**SĐT:** ' + (lead.phone || 'CHƯA CÓ SĐT') } },
            { is_short: true, text: { tag: 'lark_md', content: '**Brand:** ' + (lead.brand || 'MHpower') } },
            { is_short: true, text: { tag: 'lark_md', content: '**Mức gấp:** ' + (lead.urgency || '') } },
            { is_short: true, text: { tag: 'lark_md', content: '**Sản phẩm:** ' + (lead.suggested_product || 'Chưa rõ') } },
            { is_short: true, text: { tag: 'lark_md', content: '**Campaign:** ' + (lead.campaign_name || 'N/A') } },
            { is_short: false, text: { tag: 'lark_md', content: '**Nhu cầu:** ' + (lead.message || '').substring(0, 200) } },
            { is_short: false, text: { tag: 'lark_md', content: '**AI nhận xét:** ' + (lead.ai_reason || '') } }
          ]
        }
      ]
    }
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.buffers) staticData.buffers = {};
if (!staticData.buffer_ts) staticData.buffer_ts = {};
const psid = $('Buffer Message').first().json.psid;
const token = $('Buffer Message').first().json.token;
// DEBOUNCE: có tin mới hơn đến trong lúc Wait -> execution này cũ -> bỏ
if (staticData.buffer_ts[psid] !== token) { return []; }
// Gộp toàn bộ mảnh thành 1 tin rồi xóa buffer
const fragments = Array.isArray(staticData.buffers[psid]) ? staticData.buffers[psid] : [];
const msg_text = fragments.join('\n').trim();
delete staticData.buffers[psid];
delete staticData.buffer_ts[psid];
const sessions = staticData.sessions || {};

// One-time cleanup: remove test PSIDs
const testPrefixes = ['test_', '99999999'];
Object.keys(sessions).forEach(function(k) {
  if (testPrefixes.some(function(p) { return k.startsWith(p); })) {
    delete sessions[k];
  }
});
staticData.sessions = sessions;

const now = Date.now();

let session = null;
try {
  const dtRow = $('DT Get Session').first().json;
  if (dtRow && dtRow.session_json) session = JSON.parse(dtRow.session_json);
} catch(e) { session = null; }
if (!session) session = sessions[psid] || {
  psid,
  info: {},
  history: [],
  turn_count: 0,
  created_at: new Date().toISOString()
};

// Migration: reset sessions with old field structure (pre-Q1Q14)
const oldKeys = ['model_xe', 'hang_xe', 'dien_ap', 'dung_luong', 'khu_vuc', 'muc_do_gap'];
const hasOldStructure = Object.keys(session.info || {}).some(function(k) { return oldKeys.indexOf(k) !== -1; });
if (hasOldStructure) {
  session.info = {};
  session.history = [];
  session.is_complete = false;
  delete session.lark_created;
  staticData.sessions[psid] = session;
}

// Reset sessions where all bot responses are the error fallback
const FALLBACK_TEXT = 'Xin lỗi, tôi chưa hiểu rõ. Bạn có thể nói lại không?';
if (!hasOldStructure && !session.is_complete && session.history && session.history.length > 0) {
  const botEntries = session.history.filter(function(h) { return h.role === 'bot'; });
  const allFallback = botEntries.length > 0 && botEntries.every(function(h) { return h.text === FALLBACK_TEXT; });
  if (allFallback) {
    session.info = {};
    session.history = [];
    session.is_complete = false;
    delete session.lark_created;
    staticData.sessions[psid] = session;
  }
}

// B2: Reset incomplete sessions older than 30 days
const SESSION_TTL_DAYS = 30;
const sessionAgeMs = now - new Date(session.created_at || 0).getTime();
if (!session.is_complete && sessionAgeMs > SESSION_TTL_DAYS * 86400000 && (session.history || []).length > 0) {
  session.info = {};
  session.history = [];
  session.is_complete = false;
  delete session.lark_created;
  session.created_at = new Date().toISOString();
  staticData.sessions[psid] = session;
}

// FIX 2026-06-08: parse 'form-trong-Messenger' (Meta day noi dung form vao chat)
(function(){
  const t = msg_text || '';
  const strip = function(s){ return (s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase(); };
  const tl = strip(t);
  if (tl.indexOf('i filled out your form')===-1 && tl.indexOf('phone number')===-1 && tl.indexOf('first name')===-1) return;
  if (!session.info) session.info = {};
  const info = session.info;
  const lines = t.split('\n');
  for (let i=0;i<lines.length;i++){
    const idx = lines[i].indexOf(':'); if(idx===-1) continue;
    const label = strip(lines[i].slice(0,idx));
    const val = lines[i].slice(idx+1).trim();
    if(!val) continue;
    if(label.indexOf('first name')!==-1 && !info.name) info.name = val;
    else if(label.indexOf('phone number')!==-1){ let pd=val.replace(/[^0-9]/g,'').replace(/^84/,'0'); if(/^[1-9]\d{8}$/.test(pd)) pd='0'+pd; if(/^0\d{9}$/.test(pd) && !info.phone) info.phone=pd; }
    else if(label.indexOf('so luong xe')!==-1 && !info.q1_so_xe) info.q1_so_xe=val;
