const wasComplete = session.is_complete === true;
const newInquiry = (parsed.new_inquiry === true) && wasComplete;

let info = Object.assign({}, session.info || {});

// P1/P3 re-open: completed session + new need -> snapshot old q/r, clear, reset complete
let reengaged = false;
if (newInquiry) {
  reengaged = true;
  const qrKeys = ['q1_so_xe','q2_loai_pin_can_thay','q3_pin_hien_dung','q4_nguoi_bao_duong','q5_anh_huong_cong_viec','q6_thoi_gian_chay','q7_thoi_gian_sac','q8_gio_lam_viec','q9_dung_xe_sac','q10_tai_trong','q11_van_de_chinh','q12_ly_do_cai_thien','q13_nguoi_quyet_dinh','q14_du_kien_thay','r1_loai_xe','r2_chieu_cao_tai','r3_thoi_gian_thue','r4_dia_diem','r5_khi_nao_can'];
  const oldSummary = qrKeys.filter(function(k){ return info[k]; }).map(function(k){ return k + '=' + info[k]; }).join('; ');
  if (oldSummary) { const _pp = info.previous_inquiry ? info.previous_inquiry.split(' || ') : []; if (_pp.indexOf(oldSummary) === -1) { _pp.push(oldSummary); info.previous_inquiry = _pp.join(' || '); } }
  qrKeys.forEach(function(k){ delete info[k]; delete extracted[k]; });
  is_complete = false;
}

// merge extracted (skip phone & new_inquiry)
Object.keys(extracted).forEach(function(k) {
  if (k === 'phone' || k === 'new_inquiry') return;
  if (extracted[k] && String(extracted[k]).trim()) {
    info[k] = String(extracted[k]).trim();
  }
});

// P2: phone from user RAW message via regex (VN mobile), never trust AI digits
const phoneMatches = (msgText || '').match(/(?:\+?84|0)(?:[\s\-]?\d){9}(?!\d)/g) || [];
for (const pm of phoneMatches) {
  const normalized = pm.replace(/[\s\-]/g, '').replace(/^\+?84/, '0');
  if (/^0\d{9}$/.test(normalized)) { info.phone = normalized; break; }
}
if (!info.phone) {
  for (const h of (session.history || []).slice(0, 8)) {
    if (h.role !== 'user') continue;
    const hm = (h.text || '').match(/(?:\+?84|0)(?:[\s\-]?\d){9}(?!\d)/g) || [];
    for (const pm of hm) {
      const normalized = pm.replace(/[\s\-]/g, '').replace(/^\+?84/, '0');
      if (/^0\d{9}$/.test(normalized)) { info.phone = normalized; break; }
    }
    if (info.phone) break;
  }
}

// normalize brand
let brand = info.brand || session.brand || '';
if (brand) {
  const bl = String(brand).toLowerCase();
  if (bl.indexOf('rental') !== -1 || bl.indexOf('xe nâng') !== -1 || bl.indexOf('xe nang') !== -1 || bl.indexOf('thuê') !== -1) brand = 'MHrental';
  else if (bl.indexOf('power') !== -1 || bl.indexOf('pin') !== -1 || bl.indexOf('lithium') !== -1) brand = 'MHpower';
  else brand = '';
}
// FIX 2026-06-08: dung brand doan tu tu khoa khi AI khong set
if (!brand && msgBrandHint) brand = msgBrandHint;
if (brand) info.brand = brand;

// ===== RECRUITMENT (tuyen dung) =====
let isRecruit = (parsed.intent === 'tuyendung') || info.is_recruitment === true || !!(info.tuyen_vi_tri || info.tuyen_dia_diem || info.tuyen_kinh_nghiem);
if (isRecruit && parsed.intent !== 'tuyendung' && (info.q1_so_xe || info.r1_loai_xe)) { isRecruit = false; delete info.is_recruitment; }
if (isRecruit) info.is_recruitment = true;

const history = (session.history || []).slice();
history.push({ role: 'user', text: msgText });
history.push({ role: 'bot', text: parsed.reply || '' });
const trimmedHistory = history.slice(-20);

// ===== Tin hieu DUNG: doi gia / buc / muon dung =====
const _m = (msgText || '').toLowerCase();
const _norm = _m.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd');
const askPrice = /(gia|bao nhieu|bao gia|may tien|nhieu tien|gia sao|gia ca|chi phi|tam bao|nhieu khong)/.test(_norm);
const annoyed = /(chet me|chet cha|\bbien\b|phien|met|dieu tra|lu bu|\bdep\b|hoi nhieu|hoi gi|nhieu the|lam the|toi pham|\bchan\b|\bbuc\b|\bvl\b|\bdm\b|phat met)/.test(_norm);
const wantStop = /(thoi nha|thoi nhe|^thoi\b|dung lai|khong can|ko can|ket thuc|\bbye\b)/.test(_norm);
const hasContact = !!(info.name || info.phone);
// brand-aware completion (NGUONG THAP: vai thong tin chinh la du)
let complete = false;
let forceHandoff = false;
if (brand === 'MHrental') {
  const need = [info.r1_loai_xe, info.r2_chieu_cao_tai, info.r4_dia_diem].filter(Boolean).length;
  if (hasContact && info.r1_loai_xe && need >= 1) complete = true;
} else if (brand === 'MHpower') {
  const need = [info.q1_so_xe, (info.q2_loai_pin_can_thay || info.q3_pin_hien_dung), info.q10_tai_trong].filter(Boolean).length;
  if (hasContact && need >= 2) complete = true;
}
// HAND-OFF NGAY khi doi gia / buc / muon dung (da co lien he + brand)
if (hasContact && brand && (askPrice || annoyed || wantStop)) { complete = true; forceHandoff = true; }
// FIX 2026-06-08: form-trong-Messenger coi nhu lead hoan tat -> chot ngay (giong leadgen)
if (info.is_fb_form && hasContact) { complete = true; }
// Gioi han so cau hoi: sau 4 luot ma chua du nhung da co lien he -> chuyen sale
if (!complete && !isRecruit && hasContact && brand && (session.turn_count || 0) >= 4) { complete = true; forceHandoff = true; }
if (!isRecruit && complete) is_complete = true;

// recruitment: never trigger sales lead; fire HR alert once
if (isRecruit) { complete = false; is_complete = false; }
let recruitment_alert = false;
if (isRecruit) {
  const tuyenReady = (parsed.tuyen_complete === true) || !!(info.tuyen_vi_tri && (info.name || info.phone));
  if (tuyenReady && !info.hr_alerted) { recruitment_alert = true; info.hr_alerted = true; }
}

const effectiveWasComplete = reengaged ? false : wasComplete;
const newly_completed = is_complete && !effectiveWasComplete;

let reply = (parsed.reply || 'Cảm ơn! Cho mình hỏi thêm nhé.').substring(0, 1900);

const wasFirstMessage = (session.history || []).length === 0;
const extractedHasContent = Object.values(info).some(function(v) { return v && String(v).trim(); });
// FIX 2026-06-08: chi hoi 'pin hay xe nang' khi THAT SU chua ro brand
if (wasFirstMessage && !extractedHasContent && !isRecruit && !brand && !msgBrandHint) {
  reply = 'Em chào anh ạ. Dạ anh đang cần thuê/mua xe nâng, hay cần pin lithium cho xe vậy ạ? Em hỗ trợ mình ngay ạ.';
}
// FIX 2026-06-08: brand DA ro nhung cau tra loi van la cau routing -> thay bang cau xac nhan theo brand
if (brand && !isRecruit) {
  var _rl = String(reply || '').toLowerCase();
  var _isRouting = _rl.indexOf('hay') !== -1 && _rl.indexOf('pin') !== -1 && (_rl.indexOf('xe nâng') !== -1 || _rl.indexOf('thuê') !== -1);
  var _replyEmpty = !parsed.reply || _rl.length < 3;
  if (_isRouting || (wasFirstMessage && _replyEmpty)) {
    reply = (brand === 'MHpower')
      ? 'Dạ vâng, pin lithium cho xe nâng thì em hỗ trợ mình ngay ạ. Anh/chị cho em xin tên và số điện thoại để sale tư vấn loại pin phù hợp và báo giá nhanh nhất nhé ạ.'
      : 'Dạ vâng, về xe nâng em hỗ trợ mình ngay ạ. Anh/chị cho em xin tên và số điện thoại để sale tư vấn và báo giá nhanh nhất nhé ạ.';
  }
}

const updatedSession = Object.assign({}, session, {
  info: info,
  history: trimmedHistory,
  is_complete: is_complete,
  brand: brand,
  turn_count: (session.turn_count || 0) + 1,
  updated_at: new Date().toISOString()
});

if (newly_completed) {
  const saleName = brand === 'MHrental' ? 'Sale MHrental' : 'Sale MHpower';
  const ph = info.phone ? info.phone : 'anh/chị';
  const nm = info.name || 'anh/chị';
  if (forceHandoff && annoyed) {
    reply = 'Dạ em xin lỗi đã hỏi hơi nhiều ạ. Em dừng ở đây nhé — ' + saleName + ' sẽ gọi ' + ph + ' để tư vấn và báo giá trực tiếp cho mình ngay ạ. Cảm ơn ' + nm + '!';
  } else if (forceHandoff && askPrice) {
    reply = 'Dạ về giá em để ' + saleName + ' gọi báo chính xác cho mình qua điện thoại ạ. Sale sẽ liên hệ ' + ph + ' trong hôm nay nhé. Cảm ơn ' + nm + '!';
  } else {
    reply = 'Dạ em đã ghi nhận đủ thông tin cơ bản ạ! ' + saleName + ' sẽ gọi ' + ph + ' để tư vấn và báo giá trực tiếp cho mình sớm nhất ạ. Cảm ơn ' + nm + '!';
  }
  updatedSession.lark_created = true;
}

