const webhookData = $('Webhook FB Lead POST').first().json;
const body = webhookData.body || {};
const headers = webhookData.headers || {};
const rawBody = webhookData.rawBody || '';
const FB_APP_SECRET = '<FB_APP_SECRET>';
if (!body.entry || !Array.isArray(body.entry)) throw new Error('[Security] Invalid FB payload - missing entry array');
const sigHeader = headers['x-hub-signature-256'] || '';
if (!sigHeader.startsWith('sha256=')) throw new Error('[Security] Missing X-Hub-Signature-256 header');
if (FB_APP_SECRET !== 'CONFIGURE_FB_APP_SECRET_HERE' && rawBody) {
  const crypto = require('crypto');
  const expected = 'sha256=' + crypto.createHmac('sha256', FB_APP_SECRET).update(rawBody).digest('hex');
  if (sigHeader !== expected) throw new Error('[Security] FB webhook signature mismatch');
}
return $input.all();

