const countBySource = (items) => {
  const r = { fb: 0, gg: 0, msg: 0, other: 0 };
  for (const item of items) {
    const _dt = item.created_time || (item.fields && (item.fields['Ngày tạo'] || item.fields['Ngày'])) || 0;
    if (!inPeriod(_dt)) continue;
    const src = str(item.fields?.['Nguồn']).trim().toLowerCase();
    if (src.indexOf('messenger') !== -1) r.msg++;
    else if (src.indexOf('face') !== -1) r.fb++;
    else if (src.indexOf('google') !== -1) r.gg++;
    else r.other++;
  }
  return r;
};

