const msg = (error.message || '').toLowerCase();

const TRANSIENT = ['timeout','econnreset','econnrefused','socket hang','429','503','502','504','rate limit','network error','etimedout'];
let errorType = 'PERMANENT';
for (const p of TRANSIENT) {
  if (msg.includes(p)) { errorType = 'TRANSIENT'; break; }
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.dlq) staticData.dlq = [];
if (!staticData.retryCounts) staticData.retryCounts = {};

const execId = exec.id || 'unknown';
const retryCount = staticData.retryCounts[execId] || 0;
if (errorType === 'TRANSIENT') {
  staticData.retryCounts[execId] = retryCount + 1;
  const ks = Object.keys(staticData.retryCounts);
  if (ks.length > 500) ks.slice(0, ks.length - 500).forEach(k => delete staticData.retryCounts[k]);
}

const ts = new Date().toISOString().replace('T',' ').substring(0,19);
const emoji = errorType === 'TRANSIENT' ? '⚠️' : '🔴';
const retryInfo = errorType === 'TRANSIENT'
  ? (retryCount < 3
      ? '\n→ Lỗi tạm thời (lần ' + (retryCount+1) + '/3) - Retry trong n8n UI hoặc chờ tự phục hồi'
      : '\n→ Đã thử ' + retryCount + ' lần - cần xem thủ công!')
  : '\n→ Lỗi cố định - cần fix code/config!';

