  '\nNode: ' + (exec.lastNodeExecuted || 'N/A') +
  '\nLỗi: ' + (error.message || 'Không rõ').substring(0,200) +
  '\nLúc: ' + ts + retryInfo;

staticData.dlq.push({ ts, workflow: wf.name, errorType, message: error.message, node: exec.lastNodeExecuted, retryCount: retryCount + 1 });
if (staticData.dlq.length > 200) staticData.dlq = staticData.dlq.slice(-200);

return [{ json: {
  errorType,
  canRetry: errorType === 'TRANSIENT' && retryCount < 3,
